```python
def merge_dict(d1, d2):
    """
    Merges two dictionaries.
    If a key exists in both, the value from the second dictionary (d2) is used.
    If a key exists only in the first dictionary (d1), it is kept as is.
    If a key exists only in the second dictionary (d2), it is added to the result.
    """
    result = {}
    for key in d1:
        result[key] = d1[key]
    for key in d2:
        if key in result:
            result[key] = d2[key]
        else:
            result[key] = d2[key]
    return result

