def no_of_triangle(n):
    # Initialize count of overlapping triangles
    overlap = 0

    # Iterate over each possible row and column
    for i in range(n + 1): 
        # For each row, check if there is at least one empty cell before it
        for j in range(i):
            # If an empty cell exists, consider it as an overlap
            if not (i == n // 2 and j == (n - 1) // 2):
                overlap += 1

    return overlap

